#!/usr/bin/env python3
# Interface v4.1.7
SHELL="v417_width(){\n  local c; c=\"$(ui_installation_cols)\"\n  ((c>58)) && c=58\n  ((c<16)) && c=16\n  printf '%s' \"$((c-4))\"\n}\nv417_left(){\n  local c w; c=\"$(ui_installation_cols)\"; w=\"$(v417_width)\"\n  printf '%s' \"$(((c-w)/2))\"\n}\nv417_center(){\n  local role=\"$1\" line=\"$2\" c p\n  c=\"$(ui_installation_cols)\"; line=\"$(ui_fit \"$line\" \"$((c-2))\")\"\n  p=$(((c-${#line})/2)); ((p<0)) && p=0\n  printf '%*s' \"$p\" ''; ui_print \"$role\" \"$line\"\n}\nv417_section(){\n  local w rule; w=\"$(v417_width)\"\n  printf -v rule '%*s' \"$w\" ''; rule=\"${rule// /─}\"\n  echo; v417_center section \"$rule\"; v417_center title \"$1\"; v417_center section \"$rule\"\n}\nv417_banner(){\n  local w rule; w=\"$(v417_width)\"\n  printf -v rule '%*s' \"$w\" ''; rule=\"${rule// /━}\"\n  echo; v417_center section \"$rule\"; v417_center title 'GESTIONNAIRE BATOCERA'\n  v417_center gold '★ BLONDIN EDITION ★'; v417_center section \"$rule\"\n  v417_center gold 'v4.1.7 TEST  •  BATOCERA 44'; v417_center success '● SYSTÈME PRÊT'; echo\n}\nv417_terminal_reset(){ printf '\\033[?1003l\\033[?1006l\\033[?25h\\033[0m' >&2; }\nmanager_menu_navigation() (\n  local mode=\"${1:-single}\" index=0 previous=0 key='' second='' seq='' tail='' selected=''\n  local n=${#UI_MENU_NUMBERS[@]} i maxcols maxrows rows=0 left width top=0 bottom=0 report='' size=''\n  local b mx my r hit=-1 mouse=0\n  local mouse_re='^\\[<([0-9]+);([0-9]+);([0-9]+)([Mm])$'\n  local -a starts=() rowmap=()\n  ((n>0)) || return 2\n  size=\"$(stty size 2>/dev/null < /dev/tty)\" || size='30 80'\n  read -r maxrows maxcols <<< \"$size\"\n  [[ \"$maxcols\" =~ ^[0-9]+$ ]] || maxcols=80\n  [[ \"$maxrows\" =~ ^[0-9]+$ ]] || maxrows=30\n  width=\"$(v417_width)\"; left=\"$(v417_left)\"\n  for ((i=0;i<n;i++)); do\n    starts[i]=$rows; rowmap[rows]=$i; ((rows+=1))\n    if [[ -n \"${UI_MENU_DETAILS[$i]:-}\" ]]; then rowmap[rows]=$i; ((rows+=1)); fi\n  done\n  draw_line(){\n    local idx=\"$1\" label number state='' line=''\n    label=\"$(ui_fit \"${UI_MENU_LABELS[$idx]}\" \"$((width-8))\")\"\n    number=\"${UI_MENU_NUMBERS[$idx]}\"\n    case \"$number\" in Q) number='Q ';; *) printf -v number '%02d' \"$((10#$number))\";; esac\n    printf '%*s' \"$left\" '' >&2\n    line=\"$number  $label\"\n    if ((idx==index)); then\n      printf '\\033[1;30;47m ▸ %-*s\\033[0m\\033[K' \"$((width-3))\" \"$line\" >&2\n    else\n      case \"$label\" in\n        '✓ '*) state=$'\\033[1;32m';; '✗ '*) state=$'\\033[1;31m';;\n        '◆ '*) state=$'\\033[1;33m';; *) state=$'\\033[0;37m';;\n      esac\n      printf '   \\033[0;33m%s\\033[0m  %s%s\\033[0m\\033[K' \"$number\" \"$state\" \"$label\" >&2\n    fi\n  }\n  draw_menu(){\n    local idx state detail\n    for ((idx=0;idx<n;idx++)); do\n      draw_line \"$idx\"; printf '\\r\\n' >&2\n      detail=\"${UI_MENU_DETAILS[$idx]:-}\"\n      if [[ -n \"$detail\" ]]; then\n        case \"${UI_MENU_DETAIL_ROLES[$idx]:-info}\" in success) state=$'\\033[1;32m';; warning) state=$'\\033[1;33m';; *) state=$'\\033[0;36m';; esac\n        printf '%*s%s%s\\033[0m\\033[K\\r\\n' \"$((left+7))\" '' \"$state\" \"$(ui_fit \"$detail\" \"$((width-7))\")\" >&2\n      fi\n    done\n  }\n  redraw(){\n    ((index!=previous)) || return 0\n    if ((top>0 && bottom<=maxrows)); then\n      printf '\\033[%d;1H' \"$((top+starts[previous]))\" >&2; draw_line \"$previous\"\n      printf '\\033[%d;1H' \"$((top+starts[index]))\" >&2; draw_line \"$index\"\n      printf '\\033[%d;1H' \"$bottom\" >&2\n    else\n      printf '\\033[%dA\\r' \"$rows\" >&2; draw_menu\n    fi\n  }\n  finish(){\n    selected=\"${UI_MENU_NUMBERS[$index]}\"\n    [[ \"$selected\" == Q ]] && selected=q\n    printf '%s' \"$selected\"\n  }\n  trap v417_terminal_reset EXIT\n  trap 'exit 130' INT\n  trap 'exit 143' TERM HUP\n  printf '\\033[?25l\\r\\033[2K' >&2; draw_menu\n  if ((rows<maxrows)); then\n    printf '\\033[6n' >&2\n    if IFS= read -r -s -d R -t 0.4 report && [[ \"$report\" =~ ^$'\\033'\\[([0-9]+)\\;([0-9]+)$ ]]; then\n      bottom=$((10#${BASH_REMATCH[1]})); top=$((bottom-rows))\n      if ((top>=1 && bottom<=maxrows)); then printf '\\033[?1006h\\033[?1003h' >&2; mouse=1; else top=0; fi\n    fi\n  fi\n  while IFS= read -r -s -n 1 key; do\n    previous=$index\n    case \"$key\" in\n      $'\\033')\n        seq=''\n        if IFS= read -r -s -n 1 -t 0.18 second; then\n          seq=\"$second\"\n          if [[ \"$second\" == '[' || \"$second\" == 'O' ]]; then\n            while IFS= read -r -s -n 1 -t 0.06 tail; do\n              seq+=\"$tail\"; [[ \"$tail\" =~ [A-Za-z~] || ${#seq} -gt 40 ]] && break\n            done\n          fi\n        fi\n        if ((mouse)) && [[ \"$seq\" =~ $mouse_re ]]; then\n          b=$((10#${BASH_REMATCH[1]})); mx=$((10#${BASH_REMATCH[2]})); my=$((10#${BASH_REMATCH[3]}))\n          [[ \"${BASH_REMATCH[4]}\" == M ]] || continue\n          hit=-1; r=$((my-top))\n          if ((mx>left && mx<=left+width && r>=0 && r<rows)); then hit=${rowmap[r]:--1}; fi\n          if ((b==64)); then index=$(((index+n-1)%n))\n          elif ((b==65)); then index=$(((index+1)%n))\n          elif (((b&32)!=0)); then ((hit>=0)) && index=$hit\n          elif (((b&3)==2)); then printf 0; return 0\n          elif (((b&3)==0 && hit>=0)); then index=$hit; redraw; finish; return 0\n          else continue; fi\n        else\n          case \"$seq\" in *A) index=$(((index+n-1)%n));; *B) index=$(((index+1)%n));; '') printf 0; return 0;; *) continue;; esac\n        fi;;\n      '') finish; return 0;;\n      o|O|y|Y|n|N)\n        if [[ \"$mode\" == confirm ]]; then\n          case \"$key\" in o|O|y|Y) printf 1;; *) printf 0;; esac; return 0\n        fi;;\n      q|Q|0)\n        v417_terminal_reset; manager_quit_key \"$key\" && return 1\n        printf '%s' \"$key\"; return 0;;\n      [1-9])\n        if [[ \"$mode\" == ten && \"$key\" == 1 ]]; then\n          if IFS= read -r -s -n 1 -t 0.8 second; then [[ \"$second\" == 0 || \"$second\" == 1 ]] && key=\"1$second\"; fi\n        fi\n        printf '%s' \"$key\"; return 0;;\n      *) continue;;\n    esac\n    redraw\n  done\n  return 1\n)\n"
LAUNCHER="#!/bin/bash\nexport DISPLAY=\"${DISPLAY:-:0}\"\nexport BLONDIN_PORTS_PAD=1\nSCRIPT=/userdata/system/gestionnaire-batocera.sh\n[[ -f \"$SCRIPT\" ]] || { echo '[ERREUR] Gestionnaire introuvable.'; exit 1; }\nread -r cols rows fs x y < <(python3 - <<'PYGEO'\nimport re, subprocess\ndef run(args):\n    try: return subprocess.check_output(args,text=True,stderr=subprocess.DEVNULL,timeout=3)\n    except (OSError,subprocess.SubprocessError): return ''\nmon=[]\nfor line in run(['xrandr','--current']).splitlines():\n    m=re.search(r'^(\\S+)\\s+connected\\s+(primary\\s+)?(\\d+)x(\\d+)([+-]\\d+)([+-]\\d+)',line)\n    if m: mon.append((bool(m[2]),int(m[3]),int(m[4]),int(m[5]),int(m[6])))\nif mon:\n    primary,w,h,ox,oy=max(mon,key=lambda v:(v[1]*v[2],v[0]))\nelse:\n    m=re.search(r'dimensions:\\s+(\\d+)x(\\d+)',run(['xdpyinfo']))\n    w,h=(int(m[1]),int(m[2])) if m else (1280,800)\n    ox=oy=0\ndpi=96\nm=re.search(r'resolution:\\s+(\\d+)x(\\d+)',run(['xdpyinfo']))\nif m: dpi=max(72,min(180,int(m[2])))\ncols,rows=76,27\nfs=32\nwhile fs>10 and (cols*fs*dpi/72*.63+36>w*.91 or rows*fs*dpi/72*1.28+52>h*.91):fs-=1\nww=int(cols*fs*dpi/72*.60+24); hh=int(rows*fs*dpi/72*1.23+42)\nprint(cols,rows,fs,max(0,ox+(w-ww)//2),max(0,oy+(h-hh)//2))\nPYGEO\n)\n[[ \"$cols\" =~ ^[0-9]+$ ]] || { cols=76; rows=27; fs=17; x=0; y=0; }\nexec xterm -bg black -fg white -fa 'DejaVu Sans Mono' -fs \"$fs\" \\\n  -geometry \"${cols}x${rows}+${x}+${y}\" +bc -sb -rightbar -sl 5000 \\\n  -title 'Gestionnaire Batocera - BLONDIN EDITION' -e /bin/bash \"$SCRIPT\"\n"

def once(s,a,b):
    if s.count(a)!=1: raise RuntimeError('Ancre UI inattendue : '+a[:100])
    return s.replace(a,b,1)

def patch_manager(s):
    start=s.index('manager_menu_navigation(){')
    end=s.index('\nread_key(){',start)
    s=s[:start]+SHELL+s[end:]
    s=once(s,'ui_section(){\n','ui_section(){\n  if [[ "${BLONDIN_PORTS_PAD:-0}" == 1 ]]; then v417_section "$1"; return; fi\n')
    s=once(s,'ui_banner(){\n','ui_banner(){\n  if [[ "${BLONDIN_PORTS_PAD:-0}" == 1 ]]; then v417_banner; return; fi\n')
    s=once(s,"manager_closed_message(){ echo 'Gestionnaire fermé.'; }",
        "manager_closed_message(){ if [[ \"${BLONDIN_PORTS_PAD:-0}\" == 1 ]]; then v417_terminal_reset; fi; echo 'Gestionnaire fermé.'; }")
    a=s.index('    launcher_text = """#!/bin/bash')
    b=s.index('\n"""',a)+4
    s=s[:a]+'    launcher_text = '+repr(LAUNCHER)+s[b:]
    old="confirm(){ local ans; ans=\"$(read_key \"$1 [o/N] : \")\" || return 1; [[ \"$ans\" =~ ^[oOyY]$ ]]; }"
    new=r'''confirm(){
  local ans
  if [[ "${BLONDIN_PORTS_PAD:-0}" == 1 && -t 0 ]]; then
    local -a UI_MENU_NUMBERS=(0 1) UI_MENU_LABELS=('Non' 'Oui')
    local -a UI_MENU_DETAILS=() UI_MENU_DETAIL_ROLES=()
    echo; v417_center warning "$1"; echo
    ans="$(manager_menu_navigation confirm)" || return 1
    [[ "$ans" == 1 ]]
  else
    ans="$(read_key "$1 [o/N] : ")" || return 1
    [[ "$ans" =~ ^[oOyY]$ ]]
  fi
}'''
    s=once(s,old,new)
    a='    [[ -n "$line" ]] && ui_print "$role" "  $line"'
    if a in s:
        s=once(s,a,'    if [[ -n "$line" ]]; then\n      if [[ "${BLONDIN_PORTS_PAD:-0}" == 1 ]]; then v417_center "$role" "$line"; else ui_print "$role" "  $line"; fi\n    fi')
    return s

def patch_installer(s):
    a='if [[ ! -f "$LAUNCHER" ]]; then\n  cat > "$LAUNCHER" <<\'LAUNCHERV4\'\n'
    b='if [[ ! -f "$LAUNCHER" ]] || { grep -q "BLONDIN_PORTS_PAD=1" "$LAUNCHER" && grep -q "gestionnaire-batocera.sh" "$LAUNCHER" && grep -q "xterm" "$LAUNCHER"; }; then\n  cat > "$LAUNCHER" <<\'LAUNCHERV4\'\n'
    s=once(s,a,b)
    i=s.index(b)+len(b); j=s.index('\nLAUNCHERV4',i)
    s=s[:i]+LAUNCHER.rstrip('\n')+s[j:]
    s=once(s,"echo '[OK] Lanceur Ports existant conserve.'","echo '[INFO] Lanceur Ports personnalise conserve : centrage non modifie.'")
    return s
